import { Component, computed, input, output } from '@angular/core';
import { LoadingComponent } from '../loading/loading.component';

export type TipoEstadoTabla = 'cargando' | 'vacio' | 'sin-resultados' | 'error';

interface ConfiguracionEstadoTabla {
  icono: string;
  titulo: string;
  descripcion: string;
}

@Component({
  selector: 'tpp-table-state',
  imports: [LoadingComponent],
  templateUrl: './table-state.component.html',
  styleUrl: './table-state.component.css',
})
export class TableStateComponent {
  type = input<TipoEstadoTabla>('vacio');
  titulo = input<string>('');
  descripcion = input<string>('');
  reintentar = output<void>();

  cargando = computed(() => this.type() === 'cargando');
  mostrarReintentar = computed(() => this.type() === 'error');
  configuracion = computed(() => this.obtenerConfiguracion(this.type()));

  tituloMostrado = computed(() => this.titulo() || this.configuracion().titulo);
  descripcionMostrada = computed(() => this.descripcion() || this.configuracion().descripcion);

  obtenerConfiguracion(tipo: TipoEstadoTabla): ConfiguracionEstadoTabla {
    return this.estadoConfig[tipo] ?? this.estadoConfig['vacio'];
  }

  private readonly estadoConfig: Record<TipoEstadoTabla, ConfiguracionEstadoTabla> = {
    cargando: {
      icono: '',
      titulo: 'Cargando datos',
      descripcion: 'Por favor, espere un momento...',
    },
    vacio: {
      icono: 'ti-inbox',
      titulo: 'No hay registros',
      descripcion: 'Crea un nuevo registro para comenzar.',
    },
    'sin-resultados': {
      icono: 'ti-search',
      titulo: 'No se encontraron resultados',
      descripcion: 'Intente ajustar los filtros de búsqueda.',
    },
    error: {
      icono: 'ti-alert-triangle',
      titulo: 'Error al cargar los datos',
      descripcion: 'No se pudieron cargar los registros. Inténtelo nuevamente.',
    },
  };
}